import { dimensions } from './dimensions.js';
export const MIN_PER_DIMENSION = 3;
export const TOTAL_QUESTIONS = 18;
export const INITIAL_SCORE = 50;
export const difficultyLevel = question => question.difficultyLevel ?? ({ 基础: 2, 进阶: 3, 高阶: 4 })[question.difficulty];
// Fixed values inside the requested contribution ranges; never generated by a model.
const contributions = { correct: [0, 50, 60, 75, 90, 100], wrong: [0, 20, 30, 45, 50, 60] };
export function contributionFor(level, correct) {
  if (!Number.isInteger(level) || level < 1 || level > 5) throw new Error('Invalid CAT difficulty');
  return contributions[correct ? 'correct' : 'wrong'][level];
}
export const initialAbilities = () => dimensions.map(d => ({ dimensionId: d.id, count: 0, difficulty: 3, score: INITIAL_SCORE }));
export function updateAbility(ability, level, correct) {
  const contribution = contributionFor(level, correct);
  return { contribution, ability: { ...ability, count: ability.count + 1,
    difficulty: Math.max(1, Math.min(5, ability.difficulty + (correct ? 1 : -1))),
    score: ability.score * 0.7 + contribution * 0.3 } };
}
export function isComplete(answerCount, abilities) {
  return answerCount >= TOTAL_QUESTIONS && abilities.every(a => a.count >= MIN_PER_DIMENSION);
}
export function selectNextQuestion(bank, abilities, cursor, usedIds, random = Math.random) {
  const used = new Set(usedIds);
  for (let offset = 0; offset < abilities.length; offset++) {
    const index = (cursor + offset) % abilities.length;
    const ability = abilities[index];
    if (ability.count >= MIN_PER_DIMENSION) continue;
    const available = bank.filter(q => q.dimensionId === ability.dimensionId && !used.has(q.id));
    if (!available.length) throw new Error(`Dimension ${ability.dimensionId} has insufficient unused questions`);
    const distance = Math.min(...available.map(q => Math.abs(difficultyLevel(q) - ability.difficulty)));
    // Tie goes to the lower available tier; score uses actual question difficulty.
    const actualDifficulty = Math.min(...available.filter(q => Math.abs(difficultyLevel(q) - ability.difficulty) === distance).map(difficultyLevel));
    const candidates = available.filter(q => difficultyLevel(q) === actualDifficulty);
    const randomValue = random();
    if (!Number.isFinite(randomValue) || randomValue < 0 || randomValue >= 1) throw new Error('Invalid random value');
    const question = candidates[Math.floor(randomValue * candidates.length)];
    return { questionId: question.id, dimensionId: ability.dimensionId, dimensionCountBefore: ability.count,
      targetDifficulty: ability.difficulty, actualDifficulty, candidateIds: candidates.map(q => q.id),
      fallbackReason: distance ? '目标难度无未作答题目，使用同维度最近可用难度（同距优先较低档）' : null,
      nextCursor: (index + 1) % abilities.length };
  }
  return null;
}
export function logQuestionDecision(state, resumed = false, logger = console) {
  const decision = state.decisions[state.index];
  if (!decision) return;
  logger.info(`[AI PMCoach CAT] 第 ${state.index + 1} 题：${resumed ? '恢复已保存的抽题决策' : '抽题决策'}`, {
    sessionId: state.sessionId, 维度: dimensions[decision.dimensionId - 1].name,
    已测题数: decision.dimensionCountBefore, 目标难度: decision.targetDifficulty,
    实际难度: decision.actualDifficulty, 候选题号: decision.candidateIds,
    选中题号: decision.questionId, 回退原因: decision.fallbackReason ?? '无，命中目标档',
  });
}
export function logScoreChange(state, answer, logger = console) {
  logger.info(`[AI PMCoach CAT] 第 ${state.index} 题：分数变化`, {
    sessionId: state.sessionId, 题号: answer.questionId,
    维度: dimensions[answer.dimensionId - 1].name, 用户答案: answer.userAnswer,
    是否正确: answer.isCorrect, 是否跳过: answer.skipped,
    实际难度: answer.actualDifficulty, 贡献值: answer.contribution,
    旧分数: answer.scoreBefore, 新分数: answer.scoreAfter,
    公式: `${answer.scoreBefore} × 0.7 + ${answer.contribution} × 0.3 = ${answer.scoreAfter}`,
    调整前难度: answer.difficultyBefore, 调整后难度: answer.difficultyAfter,
  });
}
